import type { RingtoneId } from '@ordo/shared';

/**
 * The ringtones of the app (decision FS): generated by Web Audio, no file. One brick plays them: `startRingtone` for a
 * ring (looped or once, for its duration; called by the ring of the alarms only, `startRinging`), `previewRingtone` for
 * « Écouter », `playRingtone` once (a new mail).
 */

// Browsers only allow audio after a user gesture: the context is created on the first click or key press.
let audio: AudioContext | null = null;

/**
 * Audio context, created and resumed (from a user gesture: a click, a key press).
 * @returns {AudioContext | null} Context, null without audio support.
 */
function resumedAudio(): AudioContext | null {
  try {
    audio ??= new AudioContext();
    void audio.resume();
  } catch {
    // No audio support.
  }
  return audio;
}

/**
 * Prepares the audio on the first user gesture of the page, so alarms can ring later.
 * @returns {() => void} Cleanup removing the listeners.
 */
export function unlockAudioOnGesture(): () => void {
  /**
   * Creates the audio on the gesture, then stops listening.
   * @returns {void}
   */
  const unlock = () => {
    resumedAudio();
    cleanup();
  };
  /**
   * Removes the listeners.
   * @returns {void}
   */
  const cleanup = () => {
    window.removeEventListener('pointerdown', unlock);
    window.removeEventListener('keydown', unlock);
  };
  window.addEventListener('pointerdown', unlock);
  window.addEventListener('keydown', unlock);
  return cleanup;
}

/** A note of a ringtone: frequency (Hz), start and length (seconds), wave, loudness, overtones. */
interface Note {
  frequency: number;
  at: number;
  length: number;
  wave?: OscillatorType;
  gain?: number;
  /** Overtones (ratios of the frequency), quieter: a bell. */
  partials?: number[];
}

/**
 * Notes of a rising arpeggio.
 * @param {number[]} frequencies Frequencies.
 * @param {number} step Seconds between notes.
 * @param {Omit<Note, 'frequency' | 'at'>} note Length, wave, loudness.
 * @returns {Note[]} Notes.
 */
const arpeggio = (frequencies: number[], step: number, note: Omit<Note, 'frequency' | 'at'>): Note[] => frequencies.map((frequency, index) => ({ frequency, at: index * step, ...note }));

/** The bank: notes of each ringtone, and its length with the silence before it plays again (seconds). */
const RINGTONE_NOTES: Record<RingtoneId, { notes: Note[]; period: number }> = {
  // The chime of the app before the bank (880, 1 175, 1 568 Hz).
  carillon: { notes: arpeggio([880, 1175, 1568], 0.18, { length: 0.5 }), period: 1.6 },
  bip: { notes: [0, 0.25, 0.5].map((at) => ({ frequency: 1000, at, length: 0.12, wave: 'square' as const, gain: 0.08 })), period: 1.4 },
  marimba: { notes: arpeggio([523, 659, 784, 1047, 784], 0.14, { length: 0.3, wave: 'triangle', gain: 0.35 }), period: 1.5 },
  cloche: { notes: [{ frequency: 660, at: 0, length: 1.8, partials: [2.76, 5.4], gain: 0.25 }], period: 2.4 },
  reveil: { notes: Array.from({ length: 8 }, (_, index) => ({ frequency: index % 2 ? 1000 : 1400, at: index * 0.09, length: 0.08, wave: 'square' as const, gain: 0.07 })), period: 1.2 },
  harpe: { notes: arpeggio([392, 494, 587, 784, 988, 1175], 0.09, { length: 0.9, gain: 0.15 }), period: 2 },
};

/**
 * Plays the notes of a ringtone once, into a destination.
 * @param {AudioContext} context Audio.
 * @param {AudioNode} destination Where it plays.
 * @param {RingtoneId} id Ringtone.
 * @returns {void}
 */
function playNotes(context: AudioContext, destination: AudioNode, id: RingtoneId): void {
  const start = context.currentTime;
  for (const note of RINGTONE_NOTES[id].notes) {
    for (const [index, ratio] of [1, ...(note.partials ?? [])].entries()) {
      const at = start + note.at;
      const oscillator = context.createOscillator();
      const gain = context.createGain();
      oscillator.type = note.wave ?? 'sine';
      oscillator.frequency.value = note.frequency * ratio;
      gain.gain.setValueAtTime(0.0001, at);
      gain.gain.exponentialRampToValueAtTime((note.gain ?? 0.2) / (index + 1), at + 0.02);
      gain.gain.exponentialRampToValueAtTime(0.0001, at + note.length);
      oscillator.connect(gain).connect(destination);
      oscillator.start(at);
      oscillator.stop(at + note.length);
    }
  }
}

/**
 * Plays a ringtone (looped or once) for a while; silent until the page had a user gesture. Only the ring of the alarms
 * calls it (`startRinging`).
 * @param {RingtoneId} id Ringtone.
 * @param {{ loop: boolean, durationMs: number }} options Repeated during the ring or played once, and for how long.
 * @returns {() => void} Stops it now.
 */
export function startRingtone(id: RingtoneId, { loop, durationMs }: { loop: boolean; durationMs: number }): () => void {
  if (!audio || audio.state !== 'running') return () => undefined;
  const context = audio;
  const output = context.createGain();
  output.connect(context.destination);
  playNotes(context, output, id);
  const repeat = loop ? window.setInterval(() => playNotes(context, output, id), RINGTONE_NOTES[id].period * 1000) : undefined;
  /**
   * Stops the ringtone (notes under way cut).
   * @returns {void}
   */
  const stop = () => {
    window.clearInterval(repeat);
    window.clearTimeout(end);
    output.disconnect();
  };
  const end = window.setTimeout(stop, durationMs);
  return stop;
}

/**
 * Plays a ringtone once, when the page had a user gesture (a new mail).
 * @param {RingtoneId} id Ringtone.
 * @returns {void}
 */
export function playRingtone(id: RingtoneId): void {
  if (!audio || audio.state !== 'running') return;
  playNotes(audio, audio.destination, id);
}

/**
 * « Écouter »: plays a ringtone once, from the click (the audio is created then if needed).
 * @param {RingtoneId} id Ringtone.
 * @returns {void}
 */
export function previewRingtone(id: RingtoneId): void {
  const context = resumedAudio();
  if (context) playNotes(context, context.destination, id);
}
